      el('line',{class:'ln',x1:x,y1:hTop,x2:x,y2:yB},cal);
      el('text',{class:'wd',x:mid,y:hTop+hRow/2+fW*.36,'text-anchor':'middle','font-size':fW},cal).textContent=d.toUpperCase();
