    // "Fork Monday", written by hand above the ring, beside MON
    { const fz=wh*.13*1.2*P.w.s, x=cx+ww*(phone?-.17:.2)+P.w.x*ww, y=yL-wh*.02+P.w.y*ww;   // phone: left of MON, so it stays on screen
      const g=el('g',{class:'later script',transform:`translate(${x} ${y}) rotate(${-7+P.w.r})`},cal);
      el('text',{'text-anchor':phone?'end':'start','font-size':fz,x:0,y:0},g).textContent='Fork Monday'; R.w=g; }


    // the fork, lying on the page, and its long shadow (drawn first, so it starts right at the fork's edge)
    const S=ww/(phone?200:170)*P.f.s, R0=(phone?-20:-12)+P.f.r, rr=R0*Math.PI/180;
    const tipX=cx-ww*(phone?.6:.62), tipY=inkBot-wh*(phone?.04:.0);
